public static IReadOnlyList<long> Allocate(long total, int parts)
{
    var share = total / parts;
    var remainder = (int)(total % parts);
    return Enumerable.Range(0, parts)
        .Select(i => share + (i < remainder ? 1 : 0))
        .ToList();
}
// Allocate(10000, 3) => [3334, 3333, 3333]   sums to 10000
